    target_enemy = None
    min_d_en = float('inf')
    for e in enemies:
        d = distance(pos, e)
        if d < min_d_en:
            min_d_en = d
            target_enemy = e

    # Territory control: if exists, move towards largest cluster
    # Simplify: pick the first territory tile for movement if no resources/enemies
    target = None
    if resources:
        target = target_resource
    elif enemies:
        target = target_enemy
    elif territory_tiles:
        # pick the largest cluster: approximate by the first (for simplicity)
        target = territory_tiles[0]
    else:
        target = None

    # Decide movement
    if target:
        dx = 0
        dy = 0
        if target[0] > x:
            dx = 1
        elif target[0] < x:
            dx = -1
        if target[1] > y:
            dy = 1
        elif target[1] < y:
            dy = -1
    else:
        # No target; default to staying still
        dx, dy = 0, 0

    # Defensive check: keep dx, dy within [-1, 1]
    dx = max(-1, min(1, dx))
    dy = max(-1, min(1, dy))

    return [dx, dy]

